    """
    আগের POS ভুল করে বিক্রিগুলো "dashboard" হিসেবে রাখত। POS-এর কাস্টমারের ঠিকানা থাকত "POS / In-store" —
    সেগুলো POS হিসেবে ঠিক করা হয়; বাকিতে (Credit) না হলে টাকা পুরো পাওয়া ধরা হয়।
    """
    Order = apps.get_model('store', 'Order')
    old = Order.objects.filter(source='dashboard', customer__address='POS / In-store', delivery_charge=0)
    old.exclude(payment_method='Credit').update(source='pos', advance_paid=F('total_amount'))
    old.filter(payment_method='Credit').update(source='pos', advance_paid=0)


